function validate([nums, queries]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (queries.length < 1 || queries.length > 1000) return 'queries needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each nums value is an integer from 1 to 10^6.';
  if (queries.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each query is an integer from 1 to 10^6.';
  return null;
}

