function answerQueries(nums, queries) {
  nums.sort((a, b) => a - b);
  const prefix = [];
  let total = 0;
  for (const num of nums) {
    total += num;
    prefix.push(total);
  }

  const answer = [];
  for (const query of queries) {
    let left = 0;
    let right = prefix.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (prefix[mid] <= query) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    answer.push(left);
  }
  return answer;
}

