function answerQueries(nums, queries) {
  const n = nums.length;
  return queries.map(query => {
    let most = 0;
    for (let mask = 0; mask < (1 << n); mask++) {
      let sum = 0, count = 0;
      for (let j = 0; j < n; j++) if (mask & (1 << j)) { sum += nums[j]; count++; }
      if (sum <= query && count > most) most = count;
    }
    return most;
  });
}

