function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = rand() < 0.5 ? 1000000 : 5000;
    const nums = Array.from({ length: 1000 }, () => int(1, top));
    const queries = Array.from({ length: 1000 }, () => int(1, 1000000));
    return [nums, queries];
  }
  const n = int(1, 9);
  const top = rand() < 0.3 ? 3 : 20;
  const nums = Array.from({ length: n }, () => int(1, top));
  const queries = Array.from({ length: int(1, 6) }, () => int(1, top * n + 5));
  return [nums, queries];
}
